// src/pages/CalendarPage.js

import React, { useState } from 'react';
import Calendar from 'react-calendar';
import ReviewModal from '../components/ReviewModal'; // 경로가 맞는지 확인해주세요
import 'react-calendar/dist/Calendar.css';
import '../Calendar.css'; // 이 파일이 src 폴더에 있는지 확인해주세요

// 날짜를 'YYYY-MM-DD' 형식의 문자열 키로 변환하는 헬퍼 함수
const getDateKey = (date) => date.toISOString().split('T')[0];

function CalendarPage() {
  const [reviews, setReviews] = useState({});
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleDateClick = (date) => {
    setSelectedDate(date);
    setIsModalOpen(true);
  };

  const handleSaveReview = (reviewData) => {
    const dateKey = getDateKey(reviewData.date);
    setReviews(prev => ({ ...prev, [dateKey]: reviewData }));
  };

  const handleDeleteReview = (date) => {
    const dateKey = getDateKey(date);
    setReviews(prev => {
      const newReviews = { ...prev };
      delete newReviews[dateKey];
      return newReviews;
    });
  };

  // ⭐️ 핵심 기능: 캘린더의 각 날짜 칸에 표시될 콘텐츠를 정의하는 함수
  const tileContent = ({ date, view }) => {
    if (view === 'month') {
      const dateKey = getDateKey(date);
      const review = reviews[dateKey];

      // 리뷰와 포스터 경로가 존재하면, 이미지 태그를 반환합니다.
      if (review?.posterPath) {
        return (
          <div className="calendar-poster-wrapper">
            <img src={review.posterPath} alt={review.movie.movieNm} className="calendar-poster" />
          </div>
        );
      }
    }
    return null;
  };

  return (
    <div className="calendar-page-container">
      <h1 className="page-title">관람 캘린더</h1>
      <Calendar
        onClickDay={handleDateClick}
        tileContent={tileContent}
        formatDay={(locale, date) => date.getDate()}
        // ⭐️ "gregory" 대신 "US"로 변경하여 오류를 해결합니다.
        // "US" 타입이 기본값이므로 이 라인을 삭제해도 동일하게 작동합니다.
        calendarType="iso8601"
        className="my-calendar"
      />
      <ReviewModal
        isOpen={isModalOpen}
        onRequestClose={() => setIsModalOpen(false)}
        date={selectedDate}
        existingReview={reviews[getDateKey(selectedDate)]}
        onSave={handleSaveReview}
        onDelete={handleDeleteReview}
      />
    </div>
  );
}

export default CalendarPage;
